ph = 'init'
t0 = 0.0

def clamp(x, a, b):
    return max(a, min(b, x))

def control(obs):
    global ph, t0
    h = obs['hitch_deg']
    y = obs['rig']['trailer_rear'][1]
    t = obs['t']
    st = obs['status']
    if ph == 'init':
        ph = 'fwd'
        t0 = t
    if st in ('PINNED', 'JACKKNIFED') and ph == 'rev':
        ph = 'fwd'
        t0 = t
    if ph == 'fwd':
        if t - t0 < 2.0:
            return (0.0, 0.4)
        ph = 'rev'
    hdes = clamp(-2.0 * (y + 0.1), -4.0, 4.0)
    s = clamp(2.5 * (h - hdes), -25.0, 25.0)
    return (s, -0.4)

